import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(_req: Request, { params }: { params: { id: string } }) {
  const booking = await prisma.busBooking.findUnique({
    where: { id: params.id },
    include: { trip: { include: { route: { include: { operator: true } } } }, seats: true },
  });
  if (!booking) return NextResponse.json({ error: "Not found" }, { status: 404 });
  return NextResponse.json(booking);
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { busCheckoutSchema } from "@/lib/schemas";
import { runCheckout } from "@/lib/checkout";
import { randomUUID } from "crypto";

// Seat-lock guarantee: a held/booked seat must never be sellable to two people.
// We rely on the DB transaction + the (tripId, seatNo) unique constraint plus an
// explicit status check inside the transaction, so a concurrent second request
// racing for the same seat fails atomically instead of double-booking it.
export async function POST(req: Request) {
  const session = await getServerSession(authOptions);
  if (!session?.user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();
  const parsed = busCheckoutSchema.safeParse(body);
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 });
  const { tripId, seatNos, passengerName, method, msisdnOrCardRef } = parsed.data;

  const trip = await prisma.trip.findUnique({ where: { id: tripId } });
  if (!trip) return NextResponse.json({ error: "Trip not found" }, { status: 404 });

  try {
    const booking = await prisma.$transaction(async (tx) => {
      const seats = await tx.seat.findMany({ where: { tripId, seatNo: { in: seatNos } } });
      if (seats.length !== seatNos.length) throw new Error("SEAT_NOT_FOUND");
      const unavailable = seats.filter((s) => s.status !== "AVAILABLE");
      if (unavailable.length > 0) throw new Error("SEAT_TAKEN");

      const totalMinor = trip.basePriceMinor * seatNos.length;
      const newBooking = await tx.busBooking.create({
        data: {
          userId: (session.user as any).id,
          tripId,
          passengerName,
          totalMinor,
          status: "PENDING_PAYMENT",
        },
      });

      await tx.seat.updateMany({
        where: { id: { in: seats.map((s) => s.id) } },
        data: { status: "BOOKED", bookingId: newBooking.id },
      });

      return newBooking;
    });

    const idempotencyKey = `bus-${booking.id}`;
    const result = await runCheckout({
      userId: (session.user as any).id,
      vertical: "BUS",
      baseAmountMinor: trip.basePriceMinor * seatNos.length,
      method,
      msisdnOrCardRef,
      idempotencyKey,
      description: `Bus booking ${booking.id}: ${seatNos.join(", ")}`,
    });

    if (result.status === "SUCCEEDED") {
      await prisma.busBooking.update({
        where: { id: booking.id },
        data: { status: "CONFIRMED", paymentId: result.paymentId, feeWaived: result.feeWaived },
      });
    } else {
      // Payment failed: release the seats and mark cancelled.
      await prisma.seat.updateMany({
        where: { tripId, seatNo: { in: seatNos } },
        data: { status: "AVAILABLE", bookingId: null },
      });
      await prisma.busBooking.update({ where: { id: booking.id }, data: { status: "CANCELLED" } });
    }

    return NextResponse.json({
      bookingId: booking.id,
      status: result.status,
      breakdown: result.breakdown,
      feeWaived: result.feeWaived,
      reference: result.reference,
    });
  } catch (err: any) {
    if (err.message === "SEAT_TAKEN") {
      return NextResponse.json({ error: "One or more selected seats were just taken. Please reselect." }, { status: 409 });
    }
    if (err.message === "SEAT_NOT_FOUND") {
      return NextResponse.json({ error: "Invalid seat selection" }, { status: 400 });
    }
    console.error(err);
    return NextResponse.json({ error: "Checkout failed" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { computeCommissionOnTop } from "@/lib/pricing";

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const origin = searchParams.get("origin") || undefined;
  const destination = searchParams.get("destination") || undefined;

  const trips = await prisma.trip.findMany({
    where: {
      route: {
        ...(origin ? { origin: { contains: origin } } : {}),
        ...(destination ? { destination: { contains: destination } } : {}),
      },
    },
    include: {
      route: { include: { operator: true } },
      seats: true,
    },
    orderBy: { departAt: "asc" },
  });

  const results = trips.map((t) => {
    const available = t.seats.filter((s) => s.status === "AVAILABLE").length;
    const breakdown = computeCommissionOnTop("BUS", t.basePriceMinor);
    return {
      id: t.id,
      operator: t.route.operator.name,
      operatorVerified: t.route.operator.verified,
      origin: t.route.origin,
      destination: t.route.destination,
      departAt: t.departAt,
      arriveAt: t.arriveAt,
      availableSeats: available,
      totalSeats: t.totalSeats,
      priceBreakdown: breakdown,
    };
  });

  return NextResponse.json({ results });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { computeCommissionOnTop } from "@/lib/pricing";

export async function GET(_req: Request, { params }: { params: { id: string } }) {
  const trip = await prisma.trip.findUnique({
    where: { id: params.id },
    include: {
      route: { include: { operator: true } },
      seats: { orderBy: { seatNo: "asc" } },
    },
  });
  if (!trip) return NextResponse.json({ error: "Trip not found" }, { status: 404 });

  // Release stale seat holds (older than 10 minutes) so they become bookable again.
  const now = new Date();
  await prisma.seat.updateMany({
    where: { tripId: trip.id, status: "HELD", heldUntil: { lt: now } },
    data: { status: "AVAILABLE", heldUntil: null },
  });
  const seats = await prisma.seat.findMany({ where: { tripId: trip.id }, orderBy: { seatNo: "asc" } });

  return NextResponse.json({
    id: trip.id,
    operator: trip.route.operator.name,
    operatorVerified: trip.route.operator.verified,
    origin: trip.route.origin,
    destination: trip.route.destination,
    departAt: trip.departAt,
    arriveAt: trip.arriveAt,
    busPlate: trip.busPlate,
    seats: seats.map((s) => ({ id: s.id, seatNo: s.seatNo, status: s.status })),
    priceBreakdown: computeCommissionOnTop("BUS", trip.basePriceMinor),
  });
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { randomUUID } from "crypto";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { eventCheckoutSchema } from "@/lib/schemas";
import { runCheckout } from "@/lib/checkout";

export async function POST(req: Request) {
  const session = await getServerSession(authOptions);
  if (!session?.user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const parsed = eventCheckoutSchema.safeParse(await req.json());
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 });
  const { ticketTierId, quantity, method, msisdnOrCardRef } = parsed.data;

  const tier = await prisma.ticketTier.findUnique({ where: { id: ticketTierId } });
  if (!tier) return NextResponse.json({ error: "Ticket tier not found" }, { status: 404 });
  if (tier.sold + quantity > tier.quantity) {
    return NextResponse.json({ error: "Not enough tickets remaining" }, { status: 409 });
  }

  const baseAmountMinor = tier.priceMinor * quantity;
  const idempotencyKey = `event-${tier.id}-${randomUUID()}`;

  const result = await runCheckout({
    userId: (session.user as any).id,
    vertical: "EVENT",
    baseAmountMinor,
    method,
    msisdnOrCardRef,
    idempotencyKey,
    description: `Event ticket purchase ${tier.id} x${quantity}`,
  });

  const tickets = [];
  if (result.status === "SUCCEEDED") {
    await prisma.ticketTier.update({ where: { id: tier.id }, data: { sold: { increment: quantity } } });
    for (let i = 0; i < quantity; i++) {
      const ticket = await prisma.eventTicket.create({
        data: {
          userId: (session.user as any).id,
          ticketTierId: tier.id,
          qrCode: `KWETU-TIX-${randomUUID()}`,
          status: "CONFIRMED",
          totalMinor: baseAmountMinor / quantity,
          paymentId: result.paymentId,
          feeWaived: result.feeWaived,
        },
      });
      tickets.push(ticket);
    }
  }

  return NextResponse.json({ status: result.status, breakdown: result.breakdown, feeWaived: result.feeWaived, tickets });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { computeCommissionOnTop } from "@/lib/pricing";

export async function GET() {
  const events = await prisma.event.findMany({ include: { ticketTiers: true }, orderBy: { startsAt: "asc" } });
  return NextResponse.json({
    events: events.map((e) => ({
      ...e,
      ticketTiers: e.ticketTiers.map((t) => ({
        ...t,
        remaining: t.quantity - t.sold,
        breakdown: computeCommissionOnTop("EVENT", t.priceMinor),
      })),
    })),
  });
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { runCheckout } from "@/lib/checkout";
import { z } from "zod";

const bindSchema = z.object({
  quoteId: z.string(),
  method: z.enum(["AIRTEL_MONEY", "MTN_MONEY", "ZAMTEL_KWACHA", "CARD"]),
  msisdnOrCardRef: z.string().min(6),
});

export async function POST(req: Request) {
  const session = await getServerSession(authOptions);
  if (!session?.user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const parsed = bindSchema.safeParse(await req.json());
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 });

  const quote = await prisma.insuranceQuote.findUnique({ where: { id: parsed.data.quoteId } });
  if (!quote) return NextResponse.json({ error: "Quote not found or expired" }, { status: 404 });

  const result = await runCheckout({
    userId: (session.user as any).id,
    vertical: "INSURANCE",
    baseAmountMinor: quote.premiumMinor,
    method: parsed.data.method,
    msisdnOrCardRef: parsed.data.msisdnOrCardRef,
    idempotencyKey: `insurance-${quote.id}`,
    description: `Insurance policy bind for quote ${quote.id}`,
  });

  let policy = null;
  if (result.status === "SUCCEEDED") {
    policy = await prisma.insurancePolicy.create({
      data: { userId: (session.user as any).id, quoteId: quote.id, status: "BOUND", paymentId: result.paymentId },
    });
  }

  return NextResponse.json({ status: result.status, policy, breakdown: result.breakdown });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { insuranceQuoteSchema } from "@/lib/schemas";
import { computeCommissionOnTop } from "@/lib/pricing";

// Simple deterministic premium model for the demo: 3% of trip cost, min ZMW 20.
export async function POST(req: Request) {
  const parsed = insuranceQuoteSchema.safeParse(await req.json());
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 });
  const { productType, tripCostMinor } = parsed.data;

  const premiumMinor = Math.max(2000, Math.round(tripCostMinor * 0.03));
  const quote = await prisma.insuranceQuote.create({
    data: {
      productType,
      premiumMinor,
      coverageSummary:
        productType === "TRAVEL"
          ? "Trip cancellation, medical emergency abroad, baggage loss — up to ZMW 50,000 cover."
          : "Accommodation booking protection — cancellation & property damage cover up to ZMW 20,000.",
    },
  });

  return NextResponse.json({ ...quote, breakdown: computeCommissionOnTop("INSURANCE", premiumMinor) });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { landListingSchema } from "@/lib/schemas";
import { placementFeeForLand } from "@/lib/pricing";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";

export async function GET() {
  const listings = await prisma.landListing.findMany({ orderBy: { createdAt: "desc" } });
  return NextResponse.json({ listings });
}

export async function POST(req: Request) {
  const session = await getServerSession(authOptions);
  if (!session?.user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const parsed = landListingSchema.safeParse(await req.json());
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 });

  const placementFeeMinor = placementFeeForLand(parsed.data.priceMinor);
