"use client";

import { useState } from "react";
import { useSession } from "next-auth/react";
import { formatZmw } from "@/lib/money";

export default function InsurancePage() {
  const { data: session } = useSession();
  const [productType, setProductType] = useState<"TRAVEL" | "ACCOMMODATION_ADDON">("TRAVEL");
  const [tripCost, setTripCost] = useState(500);
  const [quote, setQuote] = useState<any>(null);
  const [method, setMethod] = useState("AIRTEL_MONEY");
  const [phone, setPhone] = useState("");
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  async function getQuote(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    const res = await fetch("/api/insurance/quote", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ productType, tripCostMinor: Math.round(tripCost * 100) }),
    });
    setQuote(await res.json());
    setLoading(false);
  }

  async function bind() {
    setLoading(true);
    const res = await fetch("/api/insurance/bind", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quoteId: quote.id, method, msisdnOrCardRef: phone }),
    });
    setResult(await res.json());
    setLoading(false);
  }

  return (
    <div className="mx-auto max-w-xl px-4 py-12">
      <h1 className="text-2xl font-bold text-kwetu-green">Travel & micro-insurance</h1>
      <p className="text-sm text-slate-500 mt-1">
        This add-on is normally embedded at bus/accommodation checkout — this page demonstrates the standalone
        quote-bind-claim flow.
      </p>

      {!quote && (
        <form onSubmit={getQuote} className="card mt-6 space-y-3">
          <select className="input" value={productType} onChange={(e) => setProductType(e.target.value as any)}>
            <option value="TRAVEL">Travel insurance</option>
            <option value="ACCOMMODATION_ADDON">Accommodation booking protection</option>
          </select>
          <input
            className="input"
            type="number"
            placeholder="Trip / booking cost (ZMW)"
            value={tripCost}
            onChange={(e) => setTripCost(Number(e.target.value))}
          />
          <button className="btn-primary w-full" disabled={loading}>
            {loading ? "Quoting..." : "Get quote"}
          </button>
        </form>
      )}

      {quote && !result && (
        <div className="card mt-6 space-y-3">
          <p className="text-sm">{quote.coverageSummary}</p>
          <div className="text-lg font-bold text-kwetu-green">Premium: {formatZmw(quote.breakdown.totalAmountMinor)}</div>
          <div className="text-xs text-slate-400">
            base {formatZmw(quote.breakdown.baseAmountMinor)} + agency commission {formatZmw(quote.breakdown.commissionAmountMinor)} + VAT{" "}
            {formatZmw(quote.breakdown.vatAmountMinor)}
          </div>
          <select className="input" value={method} onChange={(e) => setMethod(e.target.value)}>
            <option value="AIRTEL_MONEY">Airtel Money</option>
            <option value="MTN_MONEY">MTN Mobile Money</option>
            <option value="ZAMTEL_KWACHA">Zamtel Kwacha</option>
            <option value="CARD">Card</option>
          </select>
          <input className="input" placeholder="Phone / card ref" value={phone} onChange={(e) => setPhone(e.target.value)} />
          <button
            className="btn-accent w-full"
            disabled={!session?.user || !phone || loading}
            onClick={bind}
          >
            {!session?.user ? "Log in to bind policy" : loading ? "Processing..." : "Bind policy & pay"}
          </button>
        </div>
      )}

      {result && (
        <div className="card mt-6 text-center">
          <div className="text-4xl">{result.status === "SUCCEEDED" ? "✅" : "⚠️"}</div>
          <p className="mt-2 font-semibold">
            {result.status === "SUCCEEDED" ? "Policy bound!" : "Payment failed"}
          </p>
          {result.policy && <p className="text-sm text-slate-500">Policy ID: {result.policy.id}</p>}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { formatZmw } from "@/lib/money";

export default function LandPage() {
  const { data: session } = useSession();
  const [listings, setListings] = useState<any[]>([]);
  const [form, setForm] = useState({
    title: "",
    location: "",
    sizeAcres: 0,
    priceMinor: 0,
    description: "",
    contactPhone: "",
  });
  const [creating, setCreating] = useState(false);
  const [newListing, setNewListing] = useState<any>(null);
  const [payMethod, setPayMethod] = useState("AIRTEL_MONEY");
  const [payPhone, setPayPhone] = useState("");
  const [payMsg, setPayMsg] = useState("");

  function load() {
    fetch("/api/land").then((r) => r.json()).then((d) => setListings(d.listings || []));
  }
  useEffect(load, []);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setCreating(true);
    const res = await fetch("/api/land", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...form, priceMinor: Math.round(form.priceMinor * 100) }),
    });
    const data = await res.json();
    setCreating(false);
    if (res.ok) setNewListing(data);
  }

  async function payFee() {
    const res = await fetch(`/api/land/${newListing.id}/pay`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ method: payMethod, msisdnOrCardRef: payPhone }),
    });
    const data = await res.json();
    setPayMsg(data.status === "SUCCEEDED" ? "Placement fee paid — your listing is live!" : "Payment failed");
    load();
  }

  return (
    <div className="mx-auto max-w-3xl px-4 py-12">
      <h1 className="text-2xl font-bold text-kwetu-green">Land sales listings</h1>
      <div className="mt-6 space-y-3">
        {listings.map((l) => (
          <div key={l.id} className="card">
            <div className="font-semibold flex items-center gap-2">
              {l.title}
              {l.paidUntil && new Date(l.paidUntil) > new Date() && <span className="badge-verified">Live listing</span>}
            </div>
            <div className="text-sm text-slate-500">
              {l.location} · {l.sizeAcres} acres
            </div>
            <div className="text-sm">{l.description}</div>
            <div className="mt-1 font-semibold text-kwetu-green">{formatZmw(l.priceMinor)}</div>
            <div className="text-xs text-slate-400">Contact seller directly: {l.contactPhone}</div>
          </div>
        ))}
      </div>

      <div className="card mt-10">
        <h2 className="font-semibold">List your land</h2>
        {!session?.user && <p className="text-sm text-slate-500 mt-1">Log in to list land.</p>}
        {session?.user && !newListing && (
          <form onSubmit={submit} className="mt-3 space-y-3">
            <input className="input" placeholder="Title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} required />
            <input className="input" placeholder="Location" value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} required />
            <input
              className="input"
              type="number"
              placeholder="Size (acres)"
              value={form.sizeAcres || ""}
              onChange={(e) => setForm({ ...form, sizeAcres: Number(e.target.value) })}
              required
            />
            <input
              className="input"
              type="number"
              placeholder="Price (ZMW)"
              value={form.priceMinor || ""}
              onChange={(e) => setForm({ ...form, priceMinor: Number(e.target.value) })}
              required
            />
            <textarea className="input" placeholder="Description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} required />
            <input className="input" placeholder="Contact phone" value={form.contactPhone} onChange={(e) => setForm({ ...form, contactPhone: e.target.value })} required />
            <button className="btn-primary w-full" disabled={creating}>
              {creating ? "Creating..." : "Create listing"}
            </button>
          </form>
        )}
        {newListing && !payMsg && (
          <div className="mt-3 space-y-3">
            <p className="text-sm">
              Listing created. Pay the placement fee ({formatZmw(newListing.placementFeeMinor)}) to publish it.
            </p>
            <select className="input" value={payMethod} onChange={(e) => setPayMethod(e.target.value)}>
              <option value="AIRTEL_MONEY">Airtel Money</option>
              <option value="MTN_MONEY">MTN Mobile Money</option>
              <option value="ZAMTEL_KWACHA">Zamtel Kwacha</option>
              <option value="CARD">Card</option>
            </select>
            <input className="input" placeholder="Phone / card ref" value={payPhone} onChange={(e) => setPayPhone(e.target.value)} />
            <button className="btn-accent w-full" onClick={payFee} disabled={!payPhone}>
              Pay placement fee
            </button>
          </div>
        )}
        {payMsg && <p className="mt-3 text-kwetu-green font-medium">{payMsg}</p>}
      </div>
    </div>
  );
}

