import { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import bcrypt from "bcryptjs";
import { prisma } from "./prisma";

export const authOptions: NextAuthOptions = {
  session: { strategy: "jwt" },
  secret: process.env.NEXTAUTH_SECRET,
  pages: {
    signIn: "/login",
  },
  providers: [
    CredentialsProvider({
      name: "Credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null;
        const user = await prisma.user.findUnique({ where: { email: credentials.email } });
        if (!user) return null;
        const valid = await bcrypt.compare(credentials.password, user.passwordHash);
        if (!valid) return null;
        return { id: user.id, name: user.name, email: user.email, role: user.role } as any;
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = (user as any).id;
        token.role = (user as any).role;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        (session.user as any).id = token.id;
        (session.user as any).role = token.role;
      }
      return session;
    },
  },
};

import { prisma } from "./prisma";
import { computeCommissionOnTop, COMMISSION_RATES, isLoyaltyFeeWaiver } from "./pricing";
import { getPaymentProvider, PaymentMethod } from "./payments";
import { postLedgerTransaction, getOrCreatePlatformAccount, getOrCreateUserWalletAccount } from "./ledger";
import { LedgerAccountType } from "./ledgerAccountTypes";

export interface CheckoutParams {
  userId: string;
  vertical: keyof typeof COMMISSION_RATES;
  baseAmountMinor: number;
  method: PaymentMethod;
  msisdnOrCardRef: string;
  idempotencyKey: string;
  description: string;
}

export interface CheckoutResult {
  paymentId: string;
  status: "SUCCEEDED" | "FAILED";
  breakdown: ReturnType<typeof computeCommissionOnTop>;
  feeWaived: boolean;
  reference: string;
}

/**
 * Full checkout flow shared by every vertical:
 * 1. Look up wallet, decide loyalty fee waiver (every 5th completed booking).
 * 2. Compute commission-on-top + VAT breakdown.
 * 3. Charge via the PaymentProvider abstraction.
 * 4. On success, post the balanced double-entry ledger transaction and bump
 *    the wallet's completedBookingsCount + loyalty points.
 */
export async function runCheckout(params: CheckoutParams): Promise<CheckoutResult> {
  const wallet = await prisma.wallet.upsert({
    where: { userId: params.userId },
    update: {},
    create: { userId: params.userId },
  });

  const feeWaived = isLoyaltyFeeWaiver(wallet.completedBookingsCount);
  const breakdown = computeCommissionOnTop(params.vertical, params.baseAmountMinor);
  const chargeAmountMinor = feeWaived ? params.baseAmountMinor : breakdown.totalAmountMinor;

  const provider = getPaymentProvider();
  const chargeResult = await provider.charge({
    amountMinor: chargeAmountMinor,
    method: params.method,
    msisdnOrCardRef: params.msisdnOrCardRef,
    idempotencyKey: params.idempotencyKey,
  });

  const payment = await prisma.payment.create({
    data: {
      idempotencyKey: params.idempotencyKey,
      provider: provider.name,
      method: params.method,
      status: chargeResult.status,
      amountMinor: chargeAmountMinor,
      reference: chargeResult.reference,
    },
  });

  await prisma.commission.create({
    data: {
      paymentId: payment.id,
      vertical: params.vertical,
      baseAmountMinor: breakdown.baseAmountMinor,
      commissionAmountMinor: feeWaived ? 0 : breakdown.commissionAmountMinor,
      vatAmountMinor: feeWaived ? 0 : breakdown.vatAmountMinor,
      totalAmountMinor: chargeAmountMinor,
      ratePct: breakdown.ratePct,
    },
  });

  if (chargeResult.status === "SUCCEEDED") {
    const cashClearing = await getOrCreatePlatformAccount(LedgerAccountType.CASH_CLEARING, "Cash Clearing");
    const supplierPayable = await getOrCreatePlatformAccount(
      LedgerAccountType.SUPPLIER_PAYABLE,
      "Supplier Payable"
    );
    const revenue = await getOrCreatePlatformAccount(LedgerAccountType.KWETU_REVENUE, "Kwetu Revenue");
    const vatPayable = await getOrCreatePlatformAccount(
      LedgerAccountType.KWETU_VAT_PAYABLE,
      "Kwetu VAT Payable"
    );

    const lines = [
      { accountId: cashClearing.id, direction: "DEBIT" as const, amountMinor: chargeAmountMinor },
      { accountId: supplierPayable.id, direction: "CREDIT" as const, amountMinor: breakdown.baseAmountMinor },
    ];
    if (!feeWaived) {
      lines.push({
        accountId: revenue.id,
        direction: "CREDIT" as const,
        amountMinor: breakdown.commissionAmountMinor,
      });
      lines.push({
        accountId: vatPayable.id,
        direction: "CREDIT" as const,
        amountMinor: breakdown.vatAmountMinor,
      });
    }

    await postLedgerTransaction(prisma, {
      idempotencyKey: params.idempotencyKey,
      description: params.description,
      lines,
    });

    await prisma.wallet.update({
      where: { userId: params.userId },
      data: {
        completedBookingsCount: { increment: 1 },
        loyaltyPoints: { increment: Math.floor(chargeAmountMinor / 1000) }, // 1 point / ZMW10
      },
    });
  }

  return {
    paymentId: payment.id,
    status: chargeResult.status,
    breakdown,
    feeWaived,
    reference: chargeResult.reference,
  };
}

/**
 * Flat placement-fee checkout for rental/land listings (Verticals 5 & 6).
 * These are NOT commission-on-top — the platform never touches rent/sale
 * proceeds, only a flat listing fee, which is 100% Kwetu revenue (+ VAT).
 */
export async function runPlacementFeeCheckout(params: {
  userId: string;
  feeMinor: number;
  method: PaymentMethod;
  msisdnOrCardRef: string;
  idempotencyKey: string;
  description: string;
}) {
  const provider = getPaymentProvider();
  const chargeResult = await provider.charge({
    amountMinor: params.feeMinor,
    method: params.method,
    msisdnOrCardRef: params.msisdnOrCardRef,
    idempotencyKey: params.idempotencyKey,
  });

  const payment = await prisma.payment.create({
    data: {
      idempotencyKey: params.idempotencyKey,
      provider: provider.name,
      method: params.method,
      status: chargeResult.status,
      amountMinor: params.feeMinor,
      reference: chargeResult.reference,
    },
  });

  if (chargeResult.status === "SUCCEEDED") {
    const cashClearing = await getOrCreatePlatformAccount(LedgerAccountType.CASH_CLEARING, "Cash Clearing");
    const revenue = await getOrCreatePlatformAccount(LedgerAccountType.KWETU_REVENUE, "Kwetu Revenue");
    const vatPayable = await getOrCreatePlatformAccount(LedgerAccountType.KWETU_VAT_PAYABLE, "Kwetu VAT Payable");

    const vatAmountMinor = Math.round((params.feeMinor * 0.16) / 1.16); // fee is VAT-inclusive
    const netRevenueMinor = params.feeMinor - vatAmountMinor;

    await postLedgerTransaction(prisma, {
      idempotencyKey: params.idempotencyKey,
      description: params.description,
      lines: [
        { accountId: cashClearing.id, direction: "DEBIT", amountMinor: params.feeMinor },
        { accountId: revenue.id, direction: "CREDIT", amountMinor: netRevenueMinor },
        { accountId: vatPayable.id, direction: "CREDIT", amountMinor: vatAmountMinor },
      ],
    });
  }

  return { paymentId: payment.id, status: chargeResult.status, reference: chargeResult.reference };
}

import { Prisma, PrismaClient } from "@prisma/client";
import { prisma } from "./prisma";
import { LedgerAccountType } from "./ledgerAccountTypes";

export interface LedgerLine {
  accountId: string;
  direction: "DEBIT" | "CREDIT";
  amountMinor: number;
}

/**
 * Post a balanced double-entry transaction: total debits must equal total
 * credits. Idempotent by `idempotencyKey` — replays return the existing
 * transaction instead of double-posting.
 *
 * This is the single write path for all money movement in Kwetu: customer
 * payment, Kwetu commission, supplier payout, insurer premium, referral
 * payout, VAT.
 */
export async function postLedgerTransaction(
  tx: Prisma.TransactionClient | PrismaClient,
  params: {
    idempotencyKey: string;
    description: string;
    lines: LedgerLine[];
  }
) {
  const { idempotencyKey, description, lines } = params;

  const existing = await tx.ledgerTransaction.findUnique({
    where: { idempotencyKey },
    include: { entries: true },
  });
  if (existing) return existing;

  if (lines.length < 2) {
    throw new Error("A ledger transaction needs at least two lines");
  }
  const debits = lines.filter((l) => l.direction === "DEBIT").reduce((s, l) => s + l.amountMinor, 0);
  const credits = lines.filter((l) => l.direction === "CREDIT").reduce((s, l) => s + l.amountMinor, 0);
  if (debits !== credits) {
    throw new Error(`Unbalanced ledger transaction: debits=${debits} credits=${credits}`);
  }
  for (const l of lines) {
    if (l.amountMinor <= 0 || !Number.isInteger(l.amountMinor)) {
      throw new Error("Ledger line amounts must be positive integers (minor units)");
    }
  }

  const transaction = await tx.ledgerTransaction.create({
    data: { idempotencyKey, description },
  });

  for (const line of lines) {
    const account = await tx.ledgerAccount.findUniqueOrThrow({ where: { id: line.accountId } });
    const lastEntry = await tx.ledgerEntry.findFirst({
      where: { accountId: line.accountId },
      orderBy: { createdAt: "desc" },
    });
    const priorBalance = lastEntry?.runningBalance ?? 0;
    // Convention: CASH_CLEARING, USER_WALLET are asset-like (debit increases);
    // KWETU_REVENUE, KWETU_VAT_PAYABLE, SUPPLIER_PAYABLE, INSURER_PAYABLE,
    // REFERRAL_PAYABLE are liability/revenue-like (credit increases).
    const isAssetLike =
      account.type === LedgerAccountType.CASH_CLEARING || account.type === LedgerAccountType.USER_WALLET;
    const delta =
      line.direction === "DEBIT"
        ? isAssetLike
          ? line.amountMinor
          : -line.amountMinor
        : isAssetLike
        ? -line.amountMinor
        : line.amountMinor;
    const runningBalance = priorBalance + delta;

    await tx.ledgerEntry.create({
      data: {
        transactionId: transaction.id,
        accountId: line.accountId,
        direction: line.direction,
        amountMinor: line.amountMinor,
        runningBalance,
      },
    });
  }

  return tx.ledgerTransaction.findUniqueOrThrow({
    where: { id: transaction.id },
    include: { entries: true },
  });
}

/** Fetch or lazily create a singleton platform-level ledger account (revenue, VAT, clearing). */
export async function getOrCreatePlatformAccount(
  type: Exclude<LedgerAccountType, "USER_WALLET">,
  name: string
) {
  const existing = await prisma.ledgerAccount.findFirst({ where: { type, userId: null } });
  if (existing) return existing;
  return prisma.ledgerAccount.create({ data: { type, name } });
}

export async function getOrCreateUserWalletAccount(userId: string) {
  const existing = await prisma.ledgerAccount.findUnique({ where: { userId } });
  if (existing) return existing;
  return prisma.ledgerAccount.create({
    data: { type: LedgerAccountType.USER_WALLET, name: `Wallet:${userId}`, userId },
  });
}

/** Sum of entries reconciles: debits == credits, per transaction. Used by tests/admin reconciliation view. */
export function transactionBalances(entries: { direction: string; amountMinor: number }[]): boolean {
  const debits = entries.filter((e) => e.direction === "DEBIT").reduce((s, e) => s + e.amountMinor, 0);
  const credits = entries.filter((e) => e.direction === "CREDIT").reduce((s, e) => s + e.amountMinor, 0);
  return debits === credits;
}

// SQLite has no native enum support, so LedgerAccount.type is a plain string
// column. This module is the single source of truth for the allowed values,
// used in place of a Prisma enum import.
export const LedgerAccountType = {
